struct Scene {world_studio::Document d;WorldHeightRegion h{};world_surface::TerrainField field;~Scene(){world_height_region_clear(&h);}static float base(double x,double z,void *p){auto&s=*static_cast<Scene*>(p);float h=0;if(!world_height_region_sample(&s.h,x,z,&h))return NAN;return h+world_studio::height_delta(s.d,x,z);}bool load(const fs::path&p,std::string&e){char why[256];return world_studio::load((p/"world.studio").c_str(),d,e)&&world_height_region_load(&h,(p/"ground/showcase.height").c_str(),why,sizeof why)==1&&world_surface::bake_terrain(d.surfaces,base,this,field,e);}double ground(double x,double z){return base(x,z,this)+world_surface::terrain_offset(field,x,z);}bool water(double x,double z,float&h){float shore=0;return world_surface::river(field,x,z,h,shore);}};
struct Check{std::string name,detail;bool passed;};std::vector<Check> checks;
void ck(const std::string&n,bool p,const std::string&d=""){checks.push_back({n,d,p});}
bool eq(world_surface::Point a,world_surface::Point b){return a.x==b.x&&a.y==b.y&&a.z==b.z;}
bool same(const world_surface::Ribbon&a,const world_surface::Ribbon&b){if(a.name!=b.name||a.kind!=b.kind||a.layer!=b.layer||a.width!=b.width||a.shoulder!=b.shoulder||a.depth!=b.depth||a.smooth!=b.smooth||a.points.size()!=b.points.size())return false;for(unsigned i=0;i<a.points.size();i++)if(!eq(a.points[i],b.points[i]))return false;return true;}
int main(int argc,char**argv){if(argc!=3)return 2;fs::path np=fs::absolute(argv[1]),bp=fs::absolute(argv[2]);std::string e;Scene n,b;if(!n.load(np,e)||!b.load(bp,e)){std::cerr<<"Production decode/bake: "<<e<<'\n';return 2;}world_city_scene::Look cityLook;ck("production_city_look_decode",world_city_scene::load((np/"city.scene").c_str(),cityLook,e),e);ck("production_document_surface_and_entity_validation",world_studio::valid(n.d,e),e);world_surface::PaintField paint;ck("production_paint_bake",world_surface::bake_paint(n.d.surfaces,paint,e),e);
std::vector<world_weather_authoring::BoundArea> areas;ck("persistent_weather_bindings",world_authoring::weather_areas(n.d,areas,e),e);ck("one_authored_weather_area",areas.size()==1);ck("weather_identity13",areas.size()==1&&areas[0].id==13);if(areas.empty())return 2;
world_weather_authoring::Sample legacy;legacy.rain=b.d.look.rain;legacy.cloud=b.d.look.cloud;legacy.fog=b.d.look.fog;bool weather_ok=true,exterior=true,feather=true;double minRain=1,maxRain=0,minCloud=1,maxCloud=0,minFog=2,maxFog=0;for(unsigned t=0;t<=260;t++){world_weather_authoring::PackedFrame p;weather_ok&=world_weather_authoring::pack(n.d.weather_global,areas.data(),unsigned(areas.size()),legacy,t,p);auto s=world_weather_authoring::sample(p,-11988,5172);weather_ok&=s.rain>=.22f&&s.rain<=.38f&&s.cloud>=.78f&&s.cloud<=.90f&&s.fog>=.55f&&s.fog<=.72f&&!s.lightning_enabled&&!s.thunder_enabled;minRain=std::min(minRain,double(s.rain));maxRain=std::max(maxRain,double(s.rain));minCloud=std::min(minCloud,double(s.cloud));maxCloud=std::max(maxCloud,double(s.cloud));minFog=std::min(minFog,double(s.fog));maxFog=std::max(maxFog,double(s.fog));auto a=areas[0].area;auto out=world_weather_authoring::sample(p,a.x+a.radius+1,a.z);exterior&=out.rain==legacy.rain&&out.cloud==legacy.cloud&&out.fog==legacy.fog;auto&pa=p.areas[0];feather&=world_weather_authoring::area_weight(pa,a.x+a.inner_radius,a.z)==1&&world_weather_authoring::area_weight(pa,a.x+a.radius,a.z)==0&&std::abs(world_weather_authoring::area_weight(pa,a.x+(a.inner_radius+a.radius)/2,a.z)-.5)<1e-6;}
ck("weather_ranges_and_no_unrequested_storm",weather_ok);ck("weather_exterior_restores_legacy_exact",exterior);ck("weather_smooth_feather",feather);
unsigned creek=~0u;for(unsigned i=0;i<n.d.surfaces.ribbons.size();i++)if(n.d.surfaces.ribbons[i].name=="West woodland creek")creek=i;ck("existing_creek_found",creek<n.d.surfaces.ribbons.size());if(creek>=n.d.surfaces.ribbons.size()||creek>=b.d.surfaces.ribbons.size())return 2;auto&r=n.d.surfaces.ribbons[creek];auto&old=b.d.surfaces.ribbons[creek];bool tail=r.points.size()==old.points.size()+5;for(unsigned i=0;i<old.points.size()&&tail;i++)tail&=eq(r.points[i+5],old.points[i]);ck("original_creek_all_points_retained",tail);ck("creek_width_bank_depth_retained",r.width==old.width&&r.shoulder==old.shoulder&&r.depth==old.depth);bool other=n.d.surfaces.ribbons.size()==b.d.surfaces.ribbons.size();for(unsigned i=0;i<n.d.surfaces.ribbons.size()&&other;i++)if(i!=creek)other&=same(n.d.surfaces.ribbons[i],b.d.surfaces.ribbons[i]);ck("all_other_rivers_and_roads_exact",other);
// Read the actual production-smoothed ribbon, then query the runtime water-grid
// union and the actual terrain bake separately at half-metre travel intervals.
auto&br=n.field.ribbons[creek];double minDepth=1e9,maxGrade=0,minWater=1e9,maxWater=-1e9;unsigned wet=0,dry=0;std::vector<std::array<double,5>> samples;bool monotonic=true;for(unsigned i=1;i<r.points.size();i++)monotonic&=r.points[i].y<=r.points[i-1].y;ck("authored_downstream_heights_nonincreasing",monotonic);for(unsigned i=1;i<br.samples.size();i++){auto a=br.samples[i-1].position,c=br.samples[i].position;unsigned count=std::max(1u,unsigned(std::ceil(std::hypot(c.x-a.x,c.z-a.z)/.5)));for(unsigned j=0;j<count;j++){double t=double(j)/count,x=a.x+(c.x-a.x)*t,z=a.z+(c.z-a.z)*t;float water=0;bool w=n.water(x,z,water);if(!w){dry++;continue;}double h=n.ground(x,z),dep=water-h;minDepth=std::min(minDepth,dep);minWater=std::min(minWater,double(water));maxWater=std::max(maxWater,double(water));auto rs=n.field.river_network->surface(x,z);maxGrade=std::max(maxGrade,rs.grade);wet++;if(i<25||j==0)samples.push_back({x,z,h,water,dep});}}
ck("continuous_creek_centerline_water",wet>100&&dry==0,std::to_string(dry)+" dry samples");ck("actual_baked_creek_bed_below_water",minDepth>.35,"minimum centerline depth="+std::to_string(minDepth));ck("bounded_water_grade",maxGrade<.2,std::to_string(maxGrade));ck("bounded_upstream_water_height",minWater>7.7&&maxWater<11.55);
std::ifstream cf(np/"opening/arrival-camp.settings");world_opening_arrival_camp::Config camp;ck("actual_camp_config",world_opening_arrival_camp::parse(cf,camp,e),e);std::vector<std::array<double,2>> dryPoints{{camp.center.x,camp.center.z},{-11989.25,5180.8},{-11988,5180},{-11985.8,5173.6}};for(auto&a:camp.actors)dryPoints.push_back({a.feet.x,a.feet.z});unsigned dryChecks=0;double groundDelta=0;bool dryCamp=true;for(auto p:dryPoints){float level;dryCamp&=!n.water(p[0],p[1],level);groundDelta=std::max(groundDelta,std::abs(n.ground(p[0],p[1])-b.ground(p[0],p[1])));dryChecks++;}ck("camp_actor_and_quest_control_roots_still_dry",dryCamp);ck("camp_actor_and_control_ground_unchanged",groundDelta<1e-5,std::to_string(groundDelta));
// Compare every2m of the arrival road and retained west woodland footpath.
unsigned routeSamples=0;double routeDelta=0;bool dryRoad=true;for(unsigned i=0;i<n.field.ribbons.size();i++){auto&road=n.field.ribbons[i];if(road.source.name!="Seldonne arrival road"&&road.source.name!="West woodland loop")continue;for(auto&s:road.samples){double x=s.position.x,z=s.position.z;routeDelta=std::max(routeDelta,std::abs(n.ground(x,z)-b.ground(x,z)));if(road.source.name=="Seldonne arrival road"){float h;dryRoad&=!n.water(x,z,h);}routeSamples++;}}ck("arrival_road_stays_dry",dryRoad);ck("existing_road_and_bridge_approach_ground_unchanged",routeSamples>100&&routeDelta<1e-5,std::to_string(routeDelta));
// Jolt is production. The declared terrain fixture is sampled from production
// final height, with the same2m surface-field grid and generated bridge decks.
world_physics::Document doc;world_physics::Body terrain;terrain.id=1;terrain.name="Production-height2m-test-grid";terrain.shape=world_physics::Shape::Mesh;terrain.pose.position={-12120,0,5120};const unsigned nx=121,nz=211;for(unsigned z=0;z<nz;z++)for(unsigned x=0;x<nx;x++)terrain.vertices.push_back({double(x*2),n.ground(-12120.+x*2,5120.+z*2),double(z*2)});for(unsigned z=0;z+1<nz;z++)for(unsigned x=0;x+1<nx;x++){unsigned a=z*nx+x;terrain.triangles.push_back({a,a+nx,a+1});terrain.triangles.push_back({a+1,a+nx,a+nx+1});}doc.bodies.push_back(std::move(terrain));bool structureSame=n.d.structures.size()==b.d.structures.size();unsigned bridgeSegments=0;std::vector<world_structure::Generated> bridges;for(auto&d:n.d.structures){world_structure::Generated g;bool ok=world_structure::build(d,g,e);ck("production_structure_build_"+std::to_string(d.id),ok,e);if(!ok)continue;auto bd=std::find_if(b.d.structures.begin(),b.d.structures.end(),[&](auto&s){return s.id==d.id;});world_structure::Generated bg;if(bd==b.d.structures.end()||!world_structure::build(*bd,bg,e)||bg.segments.size()!=g.segments.size())structureSame=false;else for(unsigned i=0;i<g.segments.size();i++)structureSame&=g.segments[i].a.x==bg.segments[i].a.x&&g.segments[i].a.y==bg.segments[i].a.y&&g.segments[i].a.z==bg.segments[i].a.z&&g.segments[i].b.x==bg.segments[i].b.x&&g.segments[i].b.y==bg.segments[i].b.y&&g.segments[i].b.z==bg.segments[i].b.z&&d.width==bd->width&&d.thickness==bd->thickness;if(d.kind!=world_structure::Kind::Bridge)continue;world_physics::Body body;body.id=100+d.id;body.name="Production-generated-deck";body.shape=world_physics::Shape::Mesh;body.pose.position={d.points[0].x,0,d.points[0].z};for(auto&s:g.segments){unsigned a=body.vertices.size();for(auto v:{s.left_a,s.left_b,s.right_a,s.right_b})body.vertices.push_back({v.x-body.pose.position.x,v.y,v.z-body.pose.position.z});body.triangles.push_back({a,a+1,a+2});body.triangles.push_back({a+2,a+1,a+3});bridgeSegments++;}doc.bodies.push_back(std::move(body));bridges.push_back(std::move(g));}ck("all_generated_structure_geometry_unchanged",structureSame);world_physics::World physics;bool jolt=physics.configure(doc,e,world_physics::Profile::StaticQuery);ck("production_Jolt_fixture_configure",jolt,e);double rayError=0,bridgeError=0;unsigned rays=0,deckRays=0,bridgeBodyHits=0;bool rayOK=true,deckOK=true;if(jolt){for(auto p:dryPoints){double h=n.ground(p[0],p[1]);world_physics::Hit hit;bool q=physics.raycast({p[0],h+2,p[1]},{0,-4,0},hit)&&hit.hit;rayOK&=q;if(q)rayError=std::max(rayError,std::abs(hit.position.y-h));rays++;}for(auto&g:bridges)if(g.owner_id==2)for(auto&s:g.segments){double x=(s.a.x+s.b.x)/2,z=(s.a.z+s.b.z)/2,y=0;bool valid=world_structure::deck_height(s,x,z,y);world_physics::Hit hit;double expected=std::max(y,n.ground(x,z));bool q=valid&&physics.raycast({x,expected+1,z},{0,-2,0},hit)&&hit.hit&&(hit.body==102||hit.body==1);deckOK&=q;if(q){bridgeError=std::max(bridgeError,std::abs(hit.position.y-expected));bridgeBodyHits+=hit.body==102;}deckRays++;}}ck("camp_ground_Jolt_ray_support",jolt&&rayOK&&rayError<.03,std::to_string(rayError));ck("retained_west_footbridge_Jolt_deck_support",jolt&&deckOK&&deckRays>5&&bridgeBodyHits>2&&bridgeError<.03,std::to_string(bridgeError));auto stats=physics.stats();ck("Jolt_queries_have_no_heap_fallback",stats.query_allocations==0);
unsigned failures=0;for(auto&c:checks)failures+=!c.passed;std::cout<<std::setprecision(15)<<"{\"schema\":\"valwood.forest-scene-production-cpu-raw.v1\",\"passed\":"<<(failures?"false":"true")<<",\"gpu_used\":false,\"checks\":[";for(unsigned i=0;i<checks.size();i++){if(i)std::cout<<',';auto&c=checks[i];std::cout<<"{\"name\":"<<std::quoted(c.name)<<",\"passed\":"<<(c.passed?"true":"false")<<",\"detail\":"<<std::quoted(c.detail)<<'}';}std::cout<<"],\"failures\":"<<failures<<",\"surface_counts\":{\"images\":"<<n.d.surfaces.images.size()<<",\"layers\":"<<n.d.surfaces.layers.size()<<",\"paint\":"<<n.d.surfaces.paint.size()<<",\"ribbons\":"<<n.d.surfaces.ribbons.size()<<",\"paint_tiles\":"<<paint.tiles.size()<<",\"terrain_tiles\":"<<n.field.tiles.size()<<"},\"creek\":{\"width\":"<<r.width<<",\"banks\":"<<r.shoulder<<",\"depth\":"<<r.depth<<",\"wet_samples\":"<<wet<<",\"dry_samples\":"<<dry<<",\"minimum_measured_centerline_depth_m\":"<<minDepth<<",\"maximum_grade\":"<<maxGrade<<",\"minimum_water_y\":"<<minWater<<",\"maximum_water_y\":"<<maxWater<<"},\"camp\":{\"root_checks\":"<<dryChecks<<",\"maximum_ground_change_m\":"<<groundDelta<<"},\"routes\":{\"samples\":"<<routeSamples<<",\"maximum_ground_change_m\":"<<routeDelta<<"},\"jolt\":{\"bodies\":"<<stats.bodies<<",\"terrain_vertices\":"<<nx*nz<<",\"bridge_segments\":"<<bridgeSegments<<",\"camp_rays\":"<<rays<<",\"camp_max_ray_height_difference_m\":"<<rayError<<",\"bridge_rays\":"<<deckRays<<",\"actual_bridge_body_hits\":"<<bridgeBodyHits<<",\"bridge_max_ray_height_difference_m\":"<<bridgeError<<",\"query_heap_fallbacks\":"<<stats.query_allocations<<"},\"weather_samples\":{\"rain\":["<<minRain<<','<<maxRain<<"],\"cloud\":["<<minCloud<<','<<maxCloud<<"],\"fog\":["<<minFog<<','<<maxFog<<"]},\"creek_sample_records\":[";for(unsigned i=0;i<samples.size();i++){if(i)std::cout<<',';std::cout<<'[';for(unsigned j=0;j<5;j++){if(j)std::cout<<',';std::cout<<samples[i][j];}std::cout<<']';}std::cout<<"]}\n";return failures?1:0;}
